  SpellDefinition("magic_stone", "Piedra Mágica", 0, "Transmutación", {DndClass.druid, DndClass.sorcerer, DndClass.warlock}, damage: "1d6 + mod (con las piedras encantadas)", summary: "Encantás hasta 3 piedras que podés lanzar o usar en honda con precisión mágica."),
  SpellDefinition("mind_sliver", "Astilla Mental", 0, "Encantamiento", {DndClass.sorcerer, DndClass.warlock, DndClass.wizard}, damage: "1d6 psíquico (escala con nivel) — salvación INT", summary: "Fragmento psíquico daña y reduce la próxima salvación del objetivo."),
  SpellDefinition("snare", "Trampa Oculta", 1, "Abjuración", {DndClass.druid, DndClass.ranger, DndClass.wizard}, ritual: true, summary: "Colocás una cuerda mágica invisible que atrapa a la primera criatura mediana o menor que pase."),
  SpellDefinition("dissonant_whispers", "Susurros Disonantes", 1, "Encantamiento", {DndClass.bard}, damage: "3d6 psíquico", summary: "Solo el objetivo escucha una frase espantosa que daña y lo obliga a huir."),
