  SpellDefinition("warding_wind", "Viento Protector", 2, "Evocación", {DndClass.bard, DndClass.druid, DndClass.sorcerer, DndClass.warlock, DndClass.wizard}, concentration: true, summary: "Un viento feroz te rodea, dificultando el habla y apagando llamas pequeñas cerca."),
  SpellDefinition("zephyr_strike", "Golpe del Céfiro", 2, "Transmutación", {DndClass.ranger}, summary: "Ganás velocidad, ventaja en un ataque, y esquivás ataques de oportunidad por un turno."),
