  SpellDefinition("storm_sphere", "Esfera de Tormenta", 4, "Evocación", {DndClass.sorcerer, DndClass.wizard}, concentration: true, damage: "4d6 rayo — salvación DES (mitad si tiene éxito)", summary: "Una esfera de tormenta daña con rayos y puede cegar con relámpagos al centro."),
  SpellDefinition("vitriolic_sphere", "Esfera Vitriólica", 4, "Evocación", {DndClass.sorcerer, DndClass.wizard}, damage: "10d4 ácido inmediato — salvación DES (mitad); 5d4 más al turno siguiente", summary: "Una esfera ácida explota, daño inmediato y continuo por el ácido residual."),
