  static List<SpellDefinition> forClass(DndClass dndClass) {
    final list = all.where((s) => s.classes.contains(dndClass)).toList();
    list.sort((a, b) {
      final byLevel = a.level.compareTo(b.level);
      if (byLevel != 0) return byLevel;
      return a.name.compareTo(b.name);
    });
    return list;
  }

  static SpellDefinition? byId(String id) {
    try {
      return all.firstWhere((s) => s.id == id);
    } catch (_) {
      return null;
    }
  }

  static SpellDefinition? byName(String name) {
    try {
      return all.firstWhere((s) => s.name == name);
    } catch (_) {
      return null;
    }
  }
}
